specimens.css:
/* 状态模拟：DisclosureRow 的 :hover 无法静态触发，把 .row:hover 的两条规则原样搬到 .forceHover 上（图标淡出、箭头淡入），行色也一并取 :hover 的 secondary。 */
.row.forceHover { color: var(--dsw-alias-label-secondary); }
.row.forceHover .iconIdle { opacity: 0; }
.row.forceHover .chevronHover { opacity: 1; }

/* 状态模拟：:hover 无法静态触发，把 .root:hover 与 .header:hover 两条规则原样搬到静态类 .forceHover 上。 */
.root.forceHover { background: var(--dsw-alias-turn-trigger-bg-hover, var(--dsw-alias-interactive-bg-hover)); }
.forceHover .header { color: var(--dsw-alias-label-secondary); }
